use payment_uri::{Error, Network, PaymentRequest};

// Vectors generated by an independent bech32 encoder that reproduces the published
// BIP-173 vector exactly (`bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4`). A checksum
// is hrp-dependent, so each network needs its own -- reusing one address across
// networks yields an invalid address and tests the wrong thing.
const BC_MAINNET: &str = "bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4";
const TB_TESTNET: &str = "tb1qw508d6qejxtdg4y5r3zarvary0c5xw7kxpjzsx";
const LTC_MAINNET: &str = "ltc1qw508d6qejxtdg4y5r3zarvary0c5xw7kgmn4n9";
const BCRT_REGTEST: &str = "bcrt1qw508d6qejxtdg4y5r3zarvary0c5xw7kygt080";

/// Lowercase control: this must keep working, and it did before the change.
#[test]
fn lowercase_bech32_is_accepted() {
    let request = PaymentRequest::parse(&format!("bitcoin:{BC_MAINNET}?amount=1")).unwrap();
    let PaymentRequest::Bitcoin(request) = request else {
        panic!("expected Bitcoin request");
    };
    assert_eq!(request.network(), Network::Mainnet);
}

/// #3026 item 1: BIP-173 defines an uppercase bech32 form explicitly so QR codes can
/// use alphanumeric mode, and Bitcoin Core / BTCPay Server emit it. `segwit::decode`
/// accepts the uppercase form but returns the hrp with its case intact, so `"BC"`
/// matched no arm in `validate_address` and every such QR code was rejected.
#[test]
fn accepts_uppercase_bip173_segwit_bitcoin() {
    let uri = format!("bitcoin:{}?amount=1", BC_MAINNET.to_uppercase());
    let request = PaymentRequest::parse(&uri)
        .expect("BIP-173 uppercase bech32 form must be accepted");
    let PaymentRequest::Bitcoin(request) = request else {
        panic!("expected Bitcoin request");
    };
    assert_eq!(request.network(), Network::Mainnet);
    assert_eq!(request.amount().unwrap().as_str(), "1");
}

/// The uppercase form must also work for Litecoin, whose hrp is "ltc" rather than "bc".
#[test]
fn accepts_uppercase_bip173_segwit_litecoin() {
    let uri = format!("litecoin:{}?amount=1", LTC_MAINNET.to_uppercase());
    let request = PaymentRequest::parse(&uri)
        .expect("BIP-173 uppercase form must be accepted for Litecoin too");
    let PaymentRequest::Litecoin(request) = request else {
        panic!("expected Litecoin request");
    };
    assert_eq!(request.network(), Network::Mainnet);
}

/// Case folding must not collapse network identity: "TB" is testnet, not mainnet.
#[test]
fn uppercase_form_still_selects_the_right_network() {
    let request = PaymentRequest::parse(&format!("bitcoin:{}", TB_TESTNET.to_uppercase()))
        .expect("uppercase testnet bech32 must be accepted");
    let PaymentRequest::Bitcoin(request) = request else {
        panic!("expected Bitcoin request");
    };
    assert_eq!(request.network(), Network::Testnet);
}

/// Regtest uses the three-character hrp "bcrt"; the uppercase form must survive too.
#[test]
fn uppercase_form_works_for_regtest_hrp() {
    let request = PaymentRequest::parse(&format!("bitcoin:{}", BCRT_REGTEST.to_uppercase()))
        .expect("uppercase regtest bech32 must be accepted");
    let PaymentRequest::Bitcoin(request) = request else {
        panic!("expected Bitcoin request");
    };
    assert_eq!(request.network(), Network::Regtest);
}

/// NEGATIVE CONTROL. A test that cannot fail is not evidence, so this pins rejection
/// behaviour that must be preserved: an hrp belonging to neither chain stays invalid
/// after case folding. Without this, "accept everything" would pass the tests above.
#[test]
fn unrelated_hrp_is_still_rejected_after_case_folding() {
    // A real bech32 checksum for hrp "zz" (produced by an encoder that reproduces the
    // published BIP-173 vector), so the only reason to reject is the hrp itself
    // rather than a checksum failure. This literal is generated, verified above.
    let result = PaymentRequest::parse("bitcoin:zz1qw508d6qejxtdg4y5r3zarvary0c5xw7k3c49eg");
    assert!(
        matches!(result, Err(Error::InvalidAddress(_)) | Err(Error::MissingRecipient)),
        "unrelated hrp must be rejected, got {:?}",
        result.map(|_| "Ok")
    );
}

/// Bisq / older wallets concatenate scheme and address without a separator being
/// distinguishable under case: "BITCOIN:BC1..." must behave like "bitcoin:BC1...".
#[test]
fn uppercase_scheme_with_uppercase_address() {
    let uri = format!("BITCOIN:{}", BC_MAINNET.to_uppercase());
    let request = PaymentRequest::parse(&uri)
        .expect("an uppercase scheme must not defeat the uppercase address fix");
    let PaymentRequest::Bitcoin(request) = request else {
        panic!("expected Bitcoin request");
    };
    assert_eq!(request.network(), Network::Mainnet);
}
